-- Gathering 3, generated by scripts/gen-gathering-sql.ts. Do not edit by hand.
insert into public.gathering_scripts (series_id, season_number, week, data) values
('dark-moon', 1, 3, '{"meta":{"dc":9,"ueDc":7,"def":25,"atk":18,"reward":740,"enemy":"The Faithful","condition":"Blade and torch: when an enemy hits a friend, that friend loses 2 more HP at the start of the next round.","ueAttr":"Agility","ueTitle":"THE SCREE","barWay":"The Climb","barRisk":"Wren''s Hold"},"steps":[{"t":"tonight","text":"Tonight: the Gathering. The map goes in through the crack in the Kiln''s crown. A lamp went in before you. Tonight calls on Agility.","section":""},{"t":"section","title":"Arrival","section":"Arrival"},{"t":"say","text":"The burned country, all week. Tonight the trail ends under it: down through the crack in the Kiln''s black crown, where the air coming up is warm as breath.\n\nDown there, a girl is crying. Quietly. The way children cry when they have learned it does not help.","section":"Arrival"},{"t":"section","title":"The Approach","section":"The Approach"},{"t":"pick","vote":true,"question":"HOW DO YOU GO DOWN?","options":[{"label":"THE ROPE","desc":"one at a time. Slow, and quiet."},{"label":"THE SCREE","desc":"all together, down the slope of loose black glass beside it. Fast, and it sounds like a cart of broken crockery."}],"section":"The Approach","mode":"vote"},{"t":"say","text":"Either way somebody has to make it safe. The glassed rock offers nothing to tie to, and the scree is only waiting for a reason to move.","section":"The Approach"},{"t":"approach","title":"THE WAY DOWN","ways":[{"by":"By the rope","attr":"Craft","verb":"rig an anchor that will hold on glass"},{"by":"By the scree","attr":"Might","verb":"be the anchor"}],"reward":"+500g · **and the party strikes first**","fail":"it gives halfway, the last of the drop is a slide in a rattle of black glass, and **they strike first**","section":"The Approach"},{"t":"say","text":"You drop through into the warm dark. Below you a lamp swings, and for one heartbeat you see him: a robed figure hauling himself away up a vent in the rock, the hot air streaming past him, a small box clutched to his chest.\n\nThen the lamp swings back, and he is gone, up into the black.","section":"The Approach"},{"t":"section","title":"The Battle","section":"The Battle"},{"t":"say","text":"They are waiting for you. {N} of them, a blade in one hand and a torch in the other. They do not break when the first of them falls.","section":"The Battle"},{"t":"battle","name":"THE FAITHFUL","firstLines":["You strike first.","He strikes first."],"desc":"**Blade and torch:** when one of them lands a hit, the burn does a little more on the round after.","section":"The Battle"},{"t":"say","text":"The last one standing does not run. He looks at the blood on the floor, then at you. He sets his blade down on the stone at his feet, very carefully, the way you would put down something borrowed.","section":"The Battle"},{"t":"say","text":"He lets himself be bound. There is no fight left in it, and no roll.","section":"The Battle"},{"t":"section","title":"The United Effort","section":"The United Effort"},{"t":"say","text":"The girl is not by the table.\n\nShe ran when the fight began, for the only way out a child could see: the slope of loose black glass, and the crack of sky at the top of it. She is two-thirds of the way up, on her knees, with one fist shut tight on something and the other hand flat on the glass. She has stopped, because the slope has started to move.\n\nIt is a small sound, like a great many plates being stacked very gently.\n\nThe glass will bear one of you at a time, and perhaps not that. So the rope goes up to her a stretch at a time. One of you climbs past where the last one stopped, drives a blade into the slope, makes the rope fast to it, and comes down. Then the next.","section":"The United Effort"},{"t":"ue","section":"The United Effort"},{"t":"ueEnd","won":true,"section":"The United Effort"},{"t":"say","text":"The girl is alive. Wren. She is nine or ten, and too frightened yet to say much. Her palm is cut and bound in the same white linen.","cond":{"on":"ue","won":true},"section":"The United Effort"},{"t":"ueEnd","won":false,"section":"The United Effort"},{"t":"say","text":"When the glass has stopped she is at the foot of it, sitting up, cut in a dozen places, with her fist still shut.\n\nThe girl is alive. Wren. She is nine or ten, and too frightened yet to say much. Under the new cuts, her palm is cut and bound in the same white linen.","cond":{"on":"ue","won":false},"section":"The United Effort"},{"t":"say","text":"Her other fist is shut so tight the knuckles are white. When she opens it at last there is a chip of black glass inside, polished smooth by her thumb.","section":"The United Effort"},{"t":"act","label":"GIVE HER BACK THE EIGHT","section":"The United Effort"},{"t":"say","text":"{TAPPER} puts the eight from the ridges into her other hand, one by one.","section":"The United Effort"},{"t":"say","text":"Garrick takes off his coat, puts it round her, and says nothing at all.","section":"The United Effort"},{"t":"say","text":"Behind the stone table: the same hollow, cut to the same shape. Empty. Its rim has been swept clean. The rubbing, laid against it, fits.","section":"The United Effort"},{"t":"section","title":"Notice","section":"Notice"},{"t":"notice","lines":{"Might":"The one who put down his blade was not beaten. He stopped.","Agility":"That vent is too narrow for a man carrying anything large. Whatever is in the box is small.","Intellect":"The rim of the hollow is not dusty and not disturbed. It has been swept. Somebody tidied after.","Charm":"Wren has not looked at the captive once. She has looked at the vent four times.","Craft":"The stone case on his belt has no hinge, no catch and no seam. It was never made to be opened with a tool.","Aim":"There are {N} torches on the floor, and one bracket on the wall with nothing in it.","floor":"Down here the warm air is moving, along the stone, toward the vent. Something up there is drawing it."},"section":"Notice"},{"t":"act","label":"LOOK CLOSER","section":"Notice"},{"t":"lookCloser","lines":{"Might":"His hands are steady. He is not afraid of you.","Agility":"And light. He climbed with it under one arm.","Intellect":"Swept with a hand, not a broom. With care.","Charm":"She saw what was in it.","Craft":"It is worn smooth all over, by years of fingers that could not get in.","Aim":"The soot above it is fresh. It was lit an hour ago."},"section":"Notice"},{"t":"section","title":"The case","section":"The case"},{"t":"say","text":"On the captive''s belt hangs a small sealed case of carved stone. Seeker work, by the look of it.","section":"The case"},{"t":"act","label":"OPEN IT","section":"The case"},{"t":"say","text":"It springs open under {TAPPER}''s hand, by itself, the way every locked thing has all season.\n\nThere is nothing in it. There never was.\n\nThe captive goes very still. He is staring at the hand that opened it.\n\n*\"Seeker blood,\"* he says, so quietly it is almost a prayer.","section":"The case"},{"t":"say","text":"Inside his coat, wrapped in oilcloth and kept closer than his knife: bound pages of the Order''s scripture. Unburned, this time.","section":"The case"},{"t":"section","title":"The Verse of the Fall","section":"The Verse of the Fall"},{"t":"say","text":"*From the First Book of the Order of the Dark Moon — The Verse of the Fall.*\n\n*Hear what became of the king who would not kneel.*\n\n*After the war, he kept his people as a shepherd keeps a flock through a hard winter. The power that had answered him on the night of the dark moon did not leave him, and he shared it. Those who stood nearest him were given the first of his gifts. They no longer felt the cold, nor the blade, nor the long fear of dying. They did not tire. They did not hunger. They stood their watches without end, and never once asked to be relieved. Where his armies camped, nothing grew — and nothing needed to. In time the gift would have reached every one of his people. In time, the whole world he had saved.*","section":"The Verse of the Fall"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"They no longer felt the cold, nor the blade, nor the long fear of dying.\"*","source":"From behind the wayside shrine","section":"The Verse of the Fall","answer":"3-1"},{"t":"say","text":"The same thing. In their book, a gift.","section":"The Verse of the Fall"},{"t":"act","label":"READ ON","section":"The Verse of the Fall"},{"t":"say","text":"*There is a price for every gift, and he never spoke of this one. He never spoke a false word to his people — not one. He only kept silent about the price. A kept silence is not a lie. But it is a seam. And through that seam, in time, the Seekers came in.*","section":"The Verse of the Fall"},{"t":"match","question":"WHICH OF YOUR FRAGMENTS IS THIS?","quote":"*\"He never spoke a false word to his people — not one. He only kept silent about the price.\"*","source":"From the Blackglass","section":"The Verse of the Fall","answer":"3-3"},{"t":"act","label":"READ ON","section":"The Verse of the Fall"},{"t":"say","text":"*They had held his wall. They had wept for him on the morning of the answering. They were his own, and he loved them. But they looked at his gift and called it rot, and would not be told otherwise. So they went out into the far places of the world and gathered what they needed, and they came for him in the night, when he had never once thought to be afraid. And there, where he stood to meet them, they struck him down.*\n\n*He did not die.*\n\n*Hear this, faithful, and never let it be forgotten: he did not die. He fell where he stood, and he sleeps where he fell — the long sleep, death''s likeness and not death — while the world outside grows old and forgets his name.*","section":"The Verse of the Fall"},{"t":"act","label":"READ ON","section":"The Verse of the Fall"},{"t":"say","text":"*And the Seekers hid their work, and set their own blood as the lock upon every way they left behind, so that no hand but their children''s could ever open it.*","section":"The Verse of the Fall"},{"t":"say","text":"*Set their own blood as the lock.*\n\nThe stone case is still lying open on the floor, where it sprang.\n\nThe captive is watching you.\n\n*\"Your blood,\"* he says. *\"Their blood. The same.\"*","section":"The Verse of the Fall"},{"t":"act","label":"READ ON","section":"The Verse of the Fall"},{"t":"say","text":"*If so small a seam as a silence let them in, what would a lie do? It would throw the door wide. Therefore the faithful shall not lie. Speak true, always. Keep your counsel where you must. Hide inside the truth.*\n\n*So the faithful remember him, and give the marked blood in his name, and wait.*\n\n*Until the throne rise whole.*","section":"The Verse of the Fall"},{"t":"section","title":"Ask","section":"Ask"},{"t":"say","text":"He has listened to all of it on his knees, with the calm of a man at a service.\n\n**You may ask him.** Each of you, one question.\nThe page you have just read says what he is: *the faithful shall not lie.* Ask exactly.","section":"Ask"},{"t":"ask","rows":[{"questions":["IS YOUR KING DEAD?"],"sealed":true,"note":"","answer":"*\"He sleeps.\"*","group":"Tonight turns on these"},{"questions":["THE CHILDREN. WHY?"],"sealed":true,"note":"","answer":"*\"To wake him.\"*","group":"Tonight turns on these"},{"questions":["THE FOURTH CHILD. WHERE IS HE?"],"sealed":true,"note":"","answer":"*\"Already with us.\"*","group":"Tonight turns on these"},{"questions":["WHERE DOES HE SLEEP?"],"sealed":false,"note":"","answer":"*\"Where he fell.\"*","group":"The king"},{"questions":["WILL IT WORK?"],"sealed":false,"note":"","answer":"*\"It is written that it will.\"*","group":"The king"},{"questions":["GENERATIONS OF CHILDREN. WHY DOES HE STILL SLEEP?"],"sealed":false,"note":"","answer":"Silence.","group":"The king"},{"questions":["WHO ARE YOU?"],"sealed":false,"note":"","answer":"*\"The faithful.\"* And to whom: *\"To the king who did not kneel.\"*","group":"The faithful"},{"questions":["WHO LEADS YOU?"],"sealed":false,"note":"","answer":"*\"One whose face I''ve never seen.\"*","group":"The faithful"},{"questions":["DO YOU KNOW THIS MAN?"],"sealed":false,"note":"of Garrick","answer":"*\"No.\"*","group":"The faithful"},{"questions":["WERE YOU LYING JUST NOW?"],"sealed":false,"note":"","answer":"A look that is almost pity. *\"The faithful do not lie.\"*","group":"The faithful"},{"questions":["WILL WREN GO HOME?"],"sealed":false,"note":"","answer":"*\"She has given. She may go.\"*","group":"The children"},{"questions":["THE OTHERS YOU TOOK, BEFORE"],"sealed":false,"note":"","answer":"*\"Most went home.\"* Pressed on the charcoal woman''s nephew: *\"Him we lost.\"* *\"Not by our choosing.\"*","group":"The children"},{"questions":["WHO SCRATCHED THE NAMES?"],"sealed":false,"note":"","answer":"*\"The faithful write the names of those who will give, so that he may know them.\"*","group":"The children"},{"questions":["WHY CARRY THAT CASE?"],"sealed":false,"note":"","answer":"*\"So that we would know you.\"*","group":"This room"},{"questions":["WHAT SAT IN THAT HOLLOW?","WHAT WAS IN THE BOX?"],"sealed":false,"note":"","answer":"Silence. Not refusal: the kind that costs him. *\"Until the throne rise whole,\"* he says instead, softly, the way you would end a prayer.","group":"This room"},{"questions":["HOW DID YOU GET HERE FIRST?"],"sealed":false,"note":"","answer":"Silence.","group":"This room"}],"section":"Ask"},{"t":"say","text":"Nobody asks it. The answer comes anyway, as if the room had asked.","section":"Ask"},{"t":"section","title":"The turn","section":"The turn"},{"t":"say","text":"The ledger''s word, beside name after name after name: *given.*","section":"The turn"},{"t":"say","text":"The white linen on Wren''s hand. On Corin''s. On Tamsin''s.","section":"The turn"},{"t":"say","text":"The words cut into the beam over her bed, in the shepherd''s hut: *Until the throne rise whole.*","section":"The turn"},{"t":"say","text":"*Rise.*","section":"The turn"},{"t":"section","title":"The Cliffhanger","section":"The Cliffhanger"},{"t":"act","label":"THEN WHY ARE WE STILL ALIVE?","section":"The Cliffhanger"},{"t":"say","text":"He could keep silent. He does not. He wants you to hear it.\n\n*\"We''re not finished with you.\"*","section":"The Cliffhanger"},{"t":"say","text":"Garrick steps up to your shoulder, closer than he has stood all night, and says nothing at all.\n\nAnd every lamp in the chamber goes out at once.\n\nBlack. Wren''s hand finds somebody''s sleeve and holds on. Nobody moves. Nobody hears a thing.\n\nBy the time a lamp is lit again, fumbling, the place where he knelt is empty. His ropes lie on the stone, cut clean. One set of footprints leads away through the ash, into the dark.","section":"The Cliffhanger"},{"t":"summary","lines":["**UNDER THE KILN** · Gathering 3","{EARNED}","The party: Battle {battle} · Wren {ue:carried down whole|cut in the slide} · {asked} questions asked","You learned: **he is not dead. He sleeps.** The Seekers who struck him down are your blood. The Order is bleeding children to wake him, and its faithful cannot lie. Their prayer was never for the dead: *until the throne rise whole* means what it says.","Tomorrow: **the dark, and a set of footprints**"],"section":"The Cliffhanger"}],"ue":{"success":{"0":["You have her wrist. She weighs nothing at all. She comes down the rope inside your arm, and she does not open her fist."],"1":["One more stretch. You could almost throw the end to her, if she had a hand free to catch it.","She has seen what the rope is for. She has not moved, and that is the right thing."],"2":["You are close enough to see her shoulders shaking. You do not call to her. You make the rope fast and come down.","She has turned her head. She is watching the rope come."],"3":["You go up it the way you would cross a frozen pond: flat, and slowly, and thinking about something else. The blade goes in to the hilt. The rope is fast.","Past the first blade, and on. The glass under you ticks, and holds."]},"fail":{"0":["The whole slope lets go, with a sound like the sea. She comes down in it."],"1":["She is on her stomach now, with nothing under her feet.","She has started, very quietly, to slide."],"2":["Something lets go higher up. It comes down past her like a thrown handful of knives. She flinches. There is blood on her sleeve when it has gone by.","The glass under her tilts. She has to take her flat hand off it, and find a new place to put it."],"3":["A plate of glass the size of a door turns over without warning, and the slope takes you down it on your back. Above, the sheet she is on slides a yard, and stops.","The slope shrugs. It does it by itself, the way a sleeper turns over. She is nearer the edge of her sheet than she was."]},"between":["Below you, the bound man is watching the slope too.","The warm air coming up from below smells of struck flint.","She has not made a sound since she stopped."]}}'::jsonb)
on conflict (series_id, season_number, week) do update set data = excluded.data;
